httpx has a default timeout of 5 seconds and four separate settings: connect, read, write and pool (waiting for a free connection). Each raises its own exception: ConnectTimeout, ReadTimeout, WriteTimeout, PoolTimeout.
import httpx
timeout = httpx.Timeout(10.0, connect=3.0) # read/write/pool = 10 s, connect = 3 s
with httpx.Client(timeout=timeout) as client:
try:
print(client.get("https://httpbin.org/get").status_code)
except httpx.ConnectTimeout:
print("connect timeout — safe to retry")
except httpx.ReadTimeout:
print("read timeout — outcome unknown for non-idempotent calls")

# retry_jitter.py — retry decorator with exponential backoff + full jitter
import functools
import random
import time
class RetryableError(Exception):
"""Raise this for failures that are safe to try again."""
def __init__(self, message, retry_after=None):
super().__init__(message)
self.retry_after = retry_after # seconds, e.g. from a Retry-After header
def retry(max_attempts=4, base=0.2, cap=5.0, retry_on=(RetryableError,)):
"""Retry with 'full jitter': sleep = random(0, min(cap, base * 2**attempt))."""
def decorator(fn):
@functools.wraps(fn)
def wrapper(*args, **kwargs):
for attempt in range(max_attempts):
try:
return fn(*args, **kwargs)
except retry_on as exc:
if attempt == max_attempts - 1:
raise # out of attempts: give up
sleep = random.uniform(0, min(cap, base * 2 ** attempt))
hint = getattr(exc, "retry_after", None)
if hint is not None: # the server knows best
sleep = max(sleep, hint)
print(f"attempt {attempt + 1} failed: {exc}; sleep {sleep:.2f}s")
time.sleep(sleep)
return wrapper
return decorator
calls = {"n": 0}
@retry(max_attempts=5)
def flaky_call():
calls["n"] += 1
if calls["n"] < 3:
raise RetryableError("503 Service Unavailable")
return "ok"
if __name__ == "__main__":
print(flaky_call(), "after", calls["n"], "calls") # ok after 3 calls

# idem_app.py — Idempotency-Key middleware for FastAPI (in-memory, one process)
# pip install fastapi uvicorn httpx
import hashlib
import itertools
import time
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response
app = FastAPI()
TTL_SECONDS = 24 * 3600
STORE: dict[str, dict] = {} # key -> {"fingerprint", "status", "body", "headers", "expires"}
order_ids = itertools.count(1)
@app.middleware("http")
async def idempotency(request: Request, call_next):
if request.method not in ("POST", "PATCH"):
return await call_next(request) # GET/PUT/DELETE: idempotent already
key = request.headers.get("Idempotency-Key")
if not key:
return JSONResponse({"error": "Idempotency-Key header required"}, status_code=400)
body = await request.body()
fingerprint = hashlib.sha256(request.method.encode() + request.url.path.encode() + body).hexdigest()
client_id = request.headers.get("Authorization", "anonymous") # scope key to caller
store_key = f"{client_id}:{key}"
now = time.time()
for k in [k for k, v in STORE.items() if v["expires"] < now]:
del STORE[k] # drop expired keys (TTL)
saved = STORE.get(store_key)
if saved:
if saved["fingerprint"] != fingerprint:
return JSONResponse({"error": "key reused with a different request"}, status_code=422)
if saved["status"] is None:
return JSONResponse({"error": "original request still in progress"}, status_code=409)
return

if saved["fingerprint"] != fingerprint:
return JSONResponse({"error": "key reused with a different request"}, status_code=422)
if saved["status"] is None:
return JSONResponse({"error": "original request still in progress"}, status_code=409)
return Response(saved["body"], status_code=saved["status"],
headers={**saved["headers"], "Idempotent-Replayed": "true"})
STORE[store_key] = {"fingerprint": fingerprint, "status": None, "expires": now + TTL_SECONDS}
try:
response = await call_next(request)
except Exception:
del STORE[store_key] # crashed: let the client retry
raise
body_out = b"".join([chunk async for chunk in response.body_iterator])
headers = {"content-type": response.headers.get("content-type", "application/json")}
STORE[store_key].update(status=response.status_code, body=body_out, headers=headers)
return Response(body_out, status_code=response.status_code, headers=headers)
@app.post("/orders", status_code=201)
async def create_order(order: dict):
return {"order_id": next(order_ids), **order}
