429 Too Many Requests is defined in RFC 6585. The response MAY include Retry-After. RFC 9110 defines Retry-After as either an HTTP date or a number of seconds.
# rate_limited_app.py — one bucket per API key (TokenBucket from above)
import math
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
app = FastAPI()
buckets: dict[str, TokenBucket] = {}
@app.middleware("http")
async def rate_limit(request: Request, call_next):
client = request.headers.get("X-API-Key") or (request.client.host if request.client else "?")
allowed, wait = buckets.setdefault(client, TokenBucket(rate=1, capacity=3)).try_acquire()
if not allowed:
return JSONResponse({"error": "rate limit exceeded"}, status_code=429,
headers={"Retry-After": str(math.ceil(wait))})
return await call_next(request)
Add any route and call it five times quickly with TestClient as alice: you get [200, 200, 200, 429, 429] with Retry-After: 1, while bob still gets 200 — each key has its own bucket.

Write a CircuitBreaker class with call(fn). It opens after failure_threshold failures in a row, fails fast with CircuitOpenError while open, and lets one trial call through after reset_timeout seconds.
Solution
import time
class CircuitOpenError(Exception):
pass
class CircuitBreaker:
def __init__(self, failure_threshold=3, reset_timeout=5.0):
self.failure_threshold = failure_threshold
self.reset_timeout = reset_timeout
self.failures, self.state, self.opened_at = 0, "closed", 0.0
def call(self, fn, *args, **kwargs):
if self.state == "open":
if time.monotonic() - self.opened_at < self.reset_timeout:
raise CircuitOpenError("failing fast; dependency is down")
self.state = "half-open" # let one trial call through
try:
result = fn(*args, **kwargs)
except Exception:
self.failures += 1
if self.state == "half-open" or self.failures >= self.failure_threshold:
self.state, self.opened_at = "open", time.monotonic()
raise
self.state, self.failures = "closed", 0 # success resets everything
return result
def down():
raise ConnectionError("payment service down")
cb = CircuitBreaker(failure_threshold=3, reset_timeout=0.5)
for i in range(5):
try:
cb.call(down)
except Exception as exc:
print(i, type(exc).__name__, cb.state)
# 0-1 ConnectionError closed | 2 ConnectionError open | 3-4 CircuitOpenError open
time.sleep(0.6)
print(cb.call(lambda: "charged"), cb.state) # charged closed

Rewrite handle() with SQLite so the balance update and the processed ID are saved in one transaction.
Solution
import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE balance (user TEXT PRIMARY KEY, amount INTEGER);
CREATE TABLE processed (message_id TEXT PRIMARY KEY);
INSERT INTO balance VALUES ('alice', 0);
""")
def handle(msg):
try:
with db: # one transaction: commit both or neither
db.execute("INSERT INTO processed VALUES (?)", (msg["id"],))
db.execute("UPDATE balance SET amount = amount + ? WHERE user = ?",
(msg["amount"], msg["user"]))
except sqlite3.IntegrityError:
print("skip duplicate", msg["id"]) # primary key clash = already done
for m in [{"id": "m-1", "user": "alice", "amount": 50},
{"id": "m-1", "user": "alice", "amount": 50}]:
handle(m)
print(db.execute("SELECT amount FROM balance").fetchone()) # (50,)
The unique key on message_id makes the duplicate check atomic.
